function studyLink(url,label){return `<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`}
function studyBox(title,body){return `<details class="study-box"><summary>${title}</summary><div class="study-content">${body}</div></details>`}
function studyTable(head,rows){return '<div class="study-table-scroll"><table><thead><tr>'+head.map(x=>'<th scope="col">'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map((x,i)=>i?'<td>'+x+'</td>':'<th scope="row">'+x+'</th>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function renderPedagogy(){let html='';const fr=lang==='fr';
if(current==='corona'){
 const alb=studyLink('https://bionumbers.hms.harvard.edu/bionumber.aspx?id=100940','BioNumbers · BNID 100940');
 const igg=studyLink('https://www.mayocliniclabs.com/test-catalog/Overview/800053','Mayo Clinic · IgG');
 const fib=studyLink('https://www.mayocliniclabs.com/test-catalog/overview/40937','Mayo Clinic · '+T('fibrinogène','fibrinogen'));
 html=studyBox(T('Repères · Les protéines du sang','Background · Blood proteins'),
 '<p>'+T('Le plasma transporte les protéines autour des cellules sanguines. L’albumine transporte des molécules et contribue à la pression oncotique. Les IgG participent à la reconnaissance immunitaire. Le fibrinogène intervient dans la coagulation. Le sérum est obtenu après coagulation ; sa composition diffère du plasma.','Plasma carries proteins around blood cells. Albumin transports molecules and contributes to oncotic pressure. IgG supports immune recognition. Fibrinogen participates in coagulation. Serum is collected after clotting; its composition differs from plasma.')+'</p>'+studyTable([T('Protéine','Protein'),T('Repère humain · source','Human reference · source'),T('Scène : concentration choisie','Scene: chosen concentration')],[
 [T('Albumine','Albumin'),'39–55 g·L⁻¹ · '+T('plasma','plasma')+' · '+alb,'40 g·L⁻¹'],['IgG','7.67–15.90 g·L⁻¹ · '+T('sérum adulte','adult serum')+' · '+igg,'10 g·L⁻¹'],[T('Fibrinogène','Fibrinogen'),'2.00–3.93 g·L⁻¹ · '+T('plasma','plasma')+' · '+fib,'3 g·L⁻¹']])+
 '<p>'+T('Pour compter des molécules, on convertit la concentration massique en concentration molaire : c = ρ/M. Avec des masses moléculaires arrondies de 66,5, 150 et 340 kDa, ces trois concentrations donnent environ 89 % d’albumine, 10 % d’IgG et 1 % de fibrinogène en nombre. La scène utilise 133, 15 et 2 silhouettes, réparties aléatoirement.','To count molecules, mass concentration is converted to molar concentration: c = ρ/M. With rounded molecular masses of 66.5, 150 and 340 kDa, these three concentrations give about 89% albumin, 10% IgG and 1% fibrinogen by number. The scene uses 133, 15 and 2 randomly distributed silhouettes.')+'</p><p>'+T('Ce mélange à trois protéines rend leur abondance relative lisible. Il ne représente pas tout le protéome plasmatique. Les apolipoprotéines, le complément et de nombreuses autres protéines sont aussi présents dans le sang. Le repère sérique des IgG sert ici à choisir un ordre de grandeur, pas à définir une composition plasmatique mesurée.','This three-protein mixture makes their relative abundance visible. It does not represent the entire plasma proteome. Apolipoproteins, complement and many other proteins are also present in blood. The serum IgG reference supplies an order of magnitude here, not a measured plasma composition.')+'</p><p>'+T('La couronne n’a pas les mêmes proportions que le plasma. Les vitesses d’adsorption, de désorption et les interactions avec la surface sélectionnent les protéines. L’échange illustré ne fixe pas un ordre universel d’affinité pour toutes les IONPs.','The corona does not have the same proportions as plasma. Adsorption and desorption rates and surface interactions select proteins. The illustrated exchange does not establish a universal affinity ranking for all IONPs.')+'</p><p>'+studyLink('https://doi.org/10.1074/mcp.R200007-MCP200','N. L. Anderson, N. G. Anderson, Mol. Cell. Proteomics 2002, 1, 845–867')+' · '+studyLink('https://doi.org/10.1002/jbm.820030106','L. Vroman, A. L. Adams, J. Biomed. Mater. Res. 1969, 3, 43–67')+'</p>');
}
if(current==='fate'){
 html=studyBox(T('Repères · Comment les particules entrent-elles ?','Background · How do particles enter?'),'<p>'+T('L’endocytose englobe plusieurs voies d’entrée. La taille hydrodynamique inclut le revêtement, la couronne et les agrégats éventuels. La cellule rencontre cet objet complet. Sa taille, sa forme et ses ligands influencent la voie utilisée.','Endocytosis includes several entry pathways. Hydrodynamic size includes the coating, corona and any aggregates. The cell encounters this whole object. Its size, shape and ligands influence the uptake pathway.')+'</p>'+studyTable([T('Voie','Pathway'),T('Mécanisme et taille','Mechanism and size')],[
 [T('Endocytose à clathrine','Clathrin-mediated endocytosis'),T('Des récepteurs et un manteau de clathrine organisent l’invagination. Chez les cellules B16 étudiées par Rejman et al., des billes de latex de moins de 200 nm empruntent cette voie. Ce seuil appartient à cette expérience.','Receptors and a clathrin coat organize membrane invagination. In the B16 cells studied by Rejman et al., latex beads below 200 nm used this pathway. This threshold belongs to that experiment.')],
 [T('Voies indépendantes de la clathrine','Clathrin-independent pathways'),T('Les cavéoles et d’autres mécanismes internalisent des objets selon la membrane, les récepteurs et le type cellulaire. Une taille seule ne permet pas de choisir la voie.','Caveolae and other mechanisms internalize objects according to membrane properties, receptors and cell type. Size alone cannot identify a pathway.')],
 [T('Macropinocytose','Macropinocytosis'),T('Des replis membranaires capturent du liquide et les objets qu’il contient. La taille du macropinosome n’est pas la taille minimale des particules capturées.','Membrane ruffles capture fluid and the objects within it. Macropinosome size is not a minimum size for captured particles.')],
 [T('Phagocytose','Phagocytosis'),T('Les macrophages et d’autres phagocytes enveloppent une cible par un remodelage de l’actine. La forme au point de contact et l’opsonisation modifient la capture. Les agrégats peuvent changer la réponse.','Macrophages and other phagocytes wrap a target through actin remodeling. Shape at the contact point and opsonization affect uptake. Aggregation can change the response.')]
 ])+'<p>'+studyLink('https://doi.org/10.1042/BJ20031253','J. Rejman et al., Biochem. J. 2004, 377, 159–169')+' · '+studyLink('https://doi.org/10.1242/jcs.102.4.867','E. L. Racoosin, J. A. Swanson, J. Cell Sci. 1992, 102, 867–880')+' · '+studyLink('https://doi.org/10.1073/pnas.0600997103','J. A. Champion, S. Mitragotri, PNAS 2006, 103, 4930–4934')+'</p>');
 html+=studyBox(T('Repères · Les compartiments et leur milieu','Background · Compartments and their environment'),'<p>'+T('Une particule endocytée reste dans la lumière d’une vésicule. Elle n’est pas directement dans le cytosol. L’endosome trie les constituants, recycle une partie du contenu et mûrit vers la voie lysosomale.','An endocytosed particle remains inside a vesicle lumen. It is not directly in the cytosol. The endosome sorts components, recycles some cargo and matures toward the lysosomal pathway.')+'</p>'+studyTable([T('Compartiment','Compartment'),T('Fonction et composition','Function and composition'),T('Repères de pH','pH examples')],[
 [T('Endosome précoce','Early endosome'),T('Tri et recyclage. Domaines Rab5 ; récepteurs et macromolécules internalisés.','Sorting and recycling. Rab5 domains; internalized receptors and macromolecules.'),'≈ 6.3 [1]'],
 [T('Endosome tardif','Late endosome'),T('Conversion Rab5 → Rab7. Membranes intraluminales et contenu dirigé vers la dégradation.','Rab5 → Rab7 conversion. Intraluminal membranes and cargo directed toward degradation.'),'≈ 6.0 [1]'],
 [T('Lysosome / endolysosome','Lysosome / endolysosome'),T('Hydrolases acides : protéases, lipases et nucléases. La V-ATPase entretient l’acidité. La membrane sépare ce milieu du cytosol.','Acid hydrolases: proteases, lipases and nucleases. V-ATPase maintains acidity. The membrane separates this environment from the cytosol.'),'≈ 5.5 [1] ; 4.7–4.8 '+T('dans les macrophages de [2]','in the macrophages in [2]')]
 ])+'<p>'+T('Ces repères proviennent de systèmes et méthodes différents. L’acidification est progressive ; chaque compartiment ne possède pas un pH universel.','These examples come from different systems and methods. Acidification is progressive; each compartment does not have one universal pH.')+'</p><h4>'+T('Ions et force ionique','Ions and ionic strength')+'</h4><p>'+T('Dans les cellules J774, Sonawane et Verkman mesurent 20 → 41 mmol·L⁻¹ de Cl⁻ dans des endosomes précoces/de recyclage en environ 10 min. Le pH passe de 6,91 à 6,05. Dans la voie tardive, Cl⁻ passe de 28 à 58 mmol·L⁻¹ entre 1 et 45 min ; le pH passe de 6,85 à 5,20 [3].','In J774 cells, Sonawane and Verkman measure 20 → 41 mmol·L⁻¹ Cl⁻ in early/recycling endosomes over about 10 min. pH falls from 6.91 to 6.05. Along the late pathway, Cl⁻ rises from 28 to 58 mmol·L⁻¹ between 1 and 45 min; pH falls from 6.85 to 5.20 [3].')+'</p><p>'+T('Chakraborty et al. mesurent environ 118 mmol·L⁻¹ de Cl⁻ dans les lysosomes des modèles macrophagiques J774A.1 et THP-1 non traités [4]. Le chlorure contribue au fonctionnement des enzymes et à l’équilibre ionique.','Chakraborty et al. measure about 118 mmol·L⁻¹ Cl⁻ in lysosomes of untreated J774A.1 and THP-1 macrophage models [4]. Chloride contributes to enzyme function and ionic balance.')+'</p><p>'+T('La force ionique dépend de tous les ions : ','Ionic strength depends on all ions: ')+ '<math xmlns="http://www.w3.org/1998/Math/MathML"><mi>I</mi><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>c</mi><mi>i</mi></msub><msubsup><mi>z</mi><mi>i</mi><mn>2</mn></msubsup></math>. '+T('ci est la concentration de l’ion i et zi son nombre de charge. [Cl⁻] ne suffit donc pas à la calculer. Par comparaison, une solution idéale de NaCl à 150 mmol·L⁻¹ a I = 150 mmol·L⁻¹ ; ce calcul ne décrit pas un lysosome.','ci is the concentration of ion i and zi its charge number. [Cl⁻] alone is therefore insufficient to calculate it. For comparison, an ideal 150 mmol·L⁻¹ NaCl solution has I = 150 mmol·L⁻¹; this calculation does not describe a lysosome.')+'</p><p>'+T('Pour les IONPs, le pH, les ligands et les enzymes modifient le revêtement et peuvent favoriser la dissolution du cœur. Le fer libéré rejoint les voies de stockage et de métabolisme. La cinétique dépend du matériau et de la cellule.','For IONPs, pH, ligands and enzymes modify the coating and can promote core dissolution. Released iron enters storage and metabolic pathways. Kinetics depend on the material and cell.')+'</p><p>[1] '+studyLink('https://bionumbers.hms.harvard.edu/bionumber.aspx?id=108100','BioNumbers · BNID 108100 / Paroutis et al., 2004, fig. 1')+'<br>[2] '+studyLink('https://doi.org/10.1073/pnas.75.7.3327','S. Ohkuma, B. Poole, PNAS 1978, 75, 3327–3331')+'<br>[3] '+studyLink('https://doi.org/10.1083/jcb.200211098','N. D. Sonawane, A. S. Verkman, J. Cell Biol. 2003, 160, 1129–1138')+'<br>[4] '+studyLink('https://doi.org/10.7554/eLife.28862','K. Chakraborty et al., eLife 2017, 6, e28862')+'<br>'+studyLink('https://goldbook.iupac.org/terms/view/I03180','IUPAC Gold Book · Ionic strength · I03180')+'<br>'+studyLink('https://doi.org/10.1016/j.cell.2005.06.043','J. Rink et al., Cell 2005, 122, 735–749')+'</p>');
}
$('pedagogy').innerHTML=html;
}
